// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.workingimport com.roshan.persona.brain.memory.Memoryimport timber.log.Timberimport java.util.ArrayDeque/** * NOUS — Working Memory (Module 3 v2 — audit P0 fix). * * Strategy §3: "Working Memory (last 10 turns, in-memory, session-only)". * * Short-term buffer that holds the most recent conversation turns for instant * access by the Brain. NOT persisted to Room — cleared on process death. * * ## Why separate from EpisodicMemory? * *  - **Speed**: WorkingMemory is a pure in-memory ArrayDeque — O(1) add/remove, *    no Room/SQLCipher overhead. Brain's pre-processor reads it on every turn. *  - **Retention**: EpisodicMemory has 30-day retention + Ebbinghaus decay. *    WorkingMemory is FIFO — only the last 10 turns survive. *  - **Scope**: WorkingMemory is per-session. EpisodicMemory is cross-session. * * ## Thread safety * * All operations are `@Synchronized` — the Brain may access WorkingMemory from * multiple coroutines (pre-processor, post-processor, JIT context fetcher). * * @see <a href="docs/strategy/module-3-strategy-v2.md">§2 Memory Architecture</a> */class WorkingMemory(    /** Max turns to retain (default 10 per strategy §3). */    private val maxTurns: Int = 10,) {    private val buffer: ArrayDeque<Memory> = ArrayDeque(maxTurns)    /**     * Add a turn to the working memory.     *     * If at capacity, the oldest turn is evicted (FIFO).     */    @Synchronized    fun add(memory: Memory) {        if (buffer.size >= maxTurns) {            buffer.pollFirst()        }        buffer.addLast(memory)        Timber.tag(TAG).d("WorkingMemory: added turn (size=${buffer.size}/$maxTurns)")    }    /**     * Get all turns in chronological order (oldest first).     */    @Synchronized    fun getAll(): List<Memory> = buffer.toList()    /**     * Get the last N turns (most recent last).     */    @Synchronized    fun getRecent(n: Int): List<Memory> {        val all = buffer.toList()        return if (all.size <= n) all else all.takeLast(n)    }    /**     * Search working memory for turns containing [query] (case-insensitive substring).     */    @Synchronized    fun search(query: String): List<Memory> {        val q = query.lowercase()        return buffer.filter { it.content.lowercase().contains(q) }    }    /** Current turn count. */    @Synchronized    fun size(): Int = buffer.size    /** Clear all turns (called on session end). */    @Synchronized    fun clear() {        buffer.clear()        Timber.tag(TAG).d("WorkingMemory cleared.")    }    private companion object {        private const val TAG = "WorkingMemory"    }}